const fs = require('fs');
// Read the SQLite file as binary and search for 'emily' (case-insensitive) in the raw bytes
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('latin1');
const lower = text.toLowerCase();
let idx = 0;
while ((idx = lower.indexOf('emily', idx)) !== -1) {
  // Extract surrounding context
  const start = Math.max(0, idx - 100);
  const end = Math.min(text.length, idx + 200);
  const snippet = text.slice(start, end).replace(/[^\x20-\x7E]/g, ' ');
  console.log('--- Found at offset', idx, '---');
  console.log(snippet);
  console.log();
  idx += 5;
}
"

